//! Cargo-driven `gdi32_vista.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is gdi32_vista-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/win32ss/gdi/gdi32_vista",
        "win32ss/gdi/gdi32_vista",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "win32ss/gdi/gdi32_vista/include",
        "win32ss/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &["UNICODE", "WINVER=0x502", "_UNICODE", "_WIN32_WINNT=0x502"];

    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "___ImageBase", None),
        "x86_64" => ("x86_64-pc-windows-gnu", "__ImageBase", Some(0x7ff1d000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "__ImageBase", Some(0x7ff1d000000u64)),
        o => panic!("gdi32_vista-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:c:win32ksys", "import:user32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames"],
        "x86_64" => &["body", "engine:c:win32ksys", "import:user32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames"],
        "aarch64" => &["body", "engine:c:win32ksys", "import:user32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("gdi32_vista-rust")
        .rc("win32ss/gdi/gdi32_vista/gdi32_vista.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("win32ss/gdi/gdi32_vista/gdi32_vista.spec", "gdi32_vista.dll")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
